    "Arc mainnet · block": "Arc 主网 · 区块", "Arc RPC not reachable right now": "暂时无法连接 Arc RPC", "Nothing on this site is financial advice. Crypto assets can lose all of their value.": "本站任何内容均不构成投资建议。加密资产可能损失全部价值。",
