    "No. $ARCIRCLE launched with 100% of its 1,000,000,000 supply in the public curve. The supply split above shows where it sits today.": "没有。$ARCIRCLE 发射时 1,000,000,000 的供应 100% 放在公开曲线中。上方的供应分布显示了它现在的位置。",
