    "A fee on every $ARCIRCLE trade on its curve. It is one of the five revenue sources that feed the flywheel.": "对曲线上每笔 $ARCIRCLE 交易收取的费用，是驱动飞轮的五个收入来源之一。",
    "Do holders get rewards?": "持有人有奖励吗？",
    "A reward program for holders and creators is in design, funded by ecosystem revenue — never by new tokens. Nothing is promised until its rules are published on the": "面向持有人和创建者的奖励计划正在设计中，资金来自生态收入——绝不来自新代币。在规则发布于以下页面之前，不做任何承诺：",
