    "supporters": "人支持",
    "supporter": "人支持",
    "Support the mechanics you'd keep. You sign a message with your wallet — free, no transaction. One vote per wallet per mechanic; votes from $ARCIRCLE holders are counted separately.": "支持你想保留的机制。用钱包签名一条消息——免费，无需交易。每个钱包对每个机制一票；$ARCIRCLE 持有人的票会单独统计。",
