    "Be there when the rules are published.": "规则发布时，第一时间在场。",
    "Reward rules, the revenue split and every buyback are announced on these two channels first.": "奖励规则、收入分配和每一次回购都会首先在这两个频道公布。",
    "Launch alerts on Telegram": "Telegram 发射提醒",
    "Follow on X": "在 X 上关注",
