    "$ARCIRCLE is relaunching.": "$ARCIRCLE 正在重新发行。",
    "There is no official contract, price or chart until the new launch goes live. The contract address will be posted on this page and by": "新发行上线前没有官方合约、价格或图表。合约地址将公布在本页以及",
