    "Your USDC goes straight to Circle's CCTP contracts — ARCIRCLE PAD never holds it and takes no fee. Fees are Circle's, deducted from the amount you send; you only pay gas on the chain you send from.": "你的 USDC 直接进入 Circle 的 CCTP 合约——ARCIRCLE PAD 从不持有资金，也不收取任何费用。费用由 Circle 收取，从发送金额中扣除；你只需在发送链上支付 Gas。",
    "Attest": "证明",
    "Mint": "铸造",
    "Your USDC is burned by Circle's contract on the chain you send from.": "Circle 合约在发送链上销毁你的 USDC。",
    "Circle signs that the burn happened — seconds with Fast, after finality with Standard.": "Circle 签名确认销毁——快速模式只需几秒，标准模式需等待最终确认。",
    "The same amount of native USDC is minted to you on the other chain, delivered by Circle.": "相同数量的原生 USDC 在另一条链上铸造给你，由 Circle 送达。",
