    "Paste any Arc token. The scanner reads its contract, who can still change it, where it trades and who holds it — then sums it up in one score. It reads the chain; it can't promise a token is safe.": "粘贴任意 Arc 代币。扫描器会读取它的合约、谁还能修改它、在哪里交易、谁持有它——并汇总成一个分数。它只读取链上数据，无法保证代币安全。",
