    "Is it a standard token? Can its code be swapped out (proxy)? Was it launched on ArcPad?": "是标准代币吗？代码能否被替换（代理）？是否在 ArcPad 发行？",
    "Who owns it — and can they still mint, pause, block wallets or change fees?": "谁拥有它——还能增发、暂停、封禁钱包或修改手续费吗？",
