    "Leading": "领先",
    "How Round #1 closes": "第 1 轮如何结束",
    "The raise and the 80 / 15 / 5 split are enforced by the escrow contract, the vote by the burn-vote contract. The top contributor's 15% (over 3 days) and the airdrop are paid by the team.": "募集和 80 / 15 / 5 分配由托管合约执行，投票由销毁投票合约执行。最大参与者的 15%（分 3 天）和空投由团队支付。",
    "72h raise": "72 小时募集",
    "Anyone sends USDC for 3 days and can withdraw it until the close.": "任何人都可在 3 天内发送 USDC，并在结束前随时提取。",
    "Close & split": "结束与分配",
    "The escrow sends 80% to the recipient, 15% to the treasury, 5% to the platform.": "托管合约将 80% 发给接收方、15% 给金库、5% 给平台。",
    "The largest contributor at the close receives the 15%, over 3 days.": "结束时的最大参与者分 3 天获得 15%。",
    "Launch & airdrop": "上线与空投",
    "The coin launches on the date the vote picks. Every contributor gets an airdrop.": "代币在投票选出的日期上线，每位参与者都会获得空投。",
    "Voted date": "投票选定日期",
    "Voting opens the moment the raise closes and runs for 48 hours. Anyone holding $ARCIRCLE can vote, as many times as they like.": "募集结束的那一刻投票开启，持续 48 小时。任何持有 $ARCIRCLE 的人都可以投任意多票。",
    "— every wallet that contributes to Round #1 gets an airdrop of the new coin. The contributor list at the close is public on-chain, so anyone can check who was in and how much.": "——参与第 1 轮的每个钱包都会获得新币空投。结束时的参与者名单在链上公开，任何人都可以查看。",
    "Size and timing of the airdrop: not decided yet. They'll be announced here.": "空投的数量和时间：尚未决定，将在这里公布。",
    "Round #1 splits the raise in one transaction at the close: 80% to the recipient wallet, 15% to the treasury wallet and 5% to the platform wallet. The wallets are fixed in the escrow contract.": "第 1 轮在结束时通过一笔交易拆分募集资金：接收方钱包 80%、金库钱包 15%、平台钱包 5%。钱包地址固定在托管合约中。",
    "The 15% goes to the top contributor — the wallet with the largest contribution at the close — over 3 days. The team sends it from the treasury wallet; the escrow contract itself only sends it to the treasury wallet.": "15% 将分 3 天支付给最大参与者（结束时贡献最多的钱包）。由团队从金库钱包发送；托管合约本身只把它发送到金库钱包。",
    "The platform's 5% feeds $ARCIRCLE buybacks and promotion — the same loop, round after round.": "平台的 5% 用于 $ARCIRCLE 回购与推广——每一轮都是同样的循环。",
    "Loading the round…": "正在加载轮次…",
    "Round #1 runs on a simple escrow contract on Arc. This is exactly what it does, and what happens after.": "第 1 轮运行在 Arc 上一个简单的托管合约上。以下是它具体做什么，以及之后会发生什么。",
    "Send USDC for 72 hours. Withdraw any time before the close.": "在 72 小时内发送 USDC，结束前随时可提取。",
    "Escrow contract": "托管合约",
    "Holds every USDC. Nobody else can move it while the raise is open.": "保管所有 USDC。募集期间任何其他人都无法转移。",
    "80% · Recipient": "80% · 接收方",
    "15% · Treasury": "15% · 金库",
    "To the top contributor, over 3 days": "分 3 天支付给最大参与者",
    "5% · Platform": "5% · 平台",
    "The full CirclePad design (v2, not live yet)": "CirclePad 完整设计（v2，尚未上线）",
    "None of this runs in Round #1 — it's the longer-term design, still in review.": "这些都不在第 1 轮运行——这是长期设计，仍在审查中。",
    "80% recipient wallet / 15% treasury wallet / 5% platform wallet, paid directly at the close. The 15% goes to the top contributor over 3 days; every contributor gets an airdrop. The split below is the v2 design, not live yet.": "结束时直接支付：接收方钱包 80% / 金库钱包 15% / 平台钱包 5%。15% 分 3 天支付给最大参与者；每位参与者都会获得空投。下方的分配是 v2 设计，尚未上线。",
    "v2 design, not live yet.": "v2 设计，尚未上线。",
    "Round #1 is the simple escrow in How it works: contributors can withdraw until the close, and the split is fixed in the contract.": "第 1 轮是“运作方式”中那个简单的托管合约：结束前可随时提取，分配固定在合约中。",
    "Round #1 is. The escrow and the burn-to-vote contract are deployed on Arc mainnet (see Contracts). The lead, vesting and clawback mechanism in Safety design is the v2 design and isn't live.": "第 1 轮已上线。托管合约和销毁投票合约已部署在 Arc 主网（见合约）。安全设计中的负责人、释放和回收机制是 v2 设计，尚未上线。",
    "What do contributors get?": "参与者能得到什么？",
    "Every Round #1 contributor gets an airdrop of the new coin; its size and timing aren't decided yet. The top contributor at the close also receives the 15% share, over 3 days.": "第 1 轮的每位参与者都会获得新币空投，数量和时间尚未决定。结束时的最大参与者还将分 3 天获得 15% 的份额。",
    "Who can vote?": "谁可以投票？",
    "Anyone holding $ARCIRCLE — contributing isn't required. Every vote burns 1,000 $ARCIRCLE, and votes can't be changed or taken back.": "任何持有 $ARCIRCLE 的人——无需参与募集。每票销毁 1,000 枚 $ARCIRCLE，投票不能更改或撤回。",
    "Yes, any amount, any time until the 72 hours are up. After the close the escrow splits everything and there's nothing left to withdraw.": "可以，在 72 小时结束前随时提取任意金额。结束后托管合约会拆分全部资金，没有可提取的余额。",
    "No votes yet — the first burn sets the lead.": "还没有投票——第一笔销毁将决定领先者。",
    "USDC sits in an escrow contract and you can withdraw your own contribution any time before the 72 hours are up. At the close it splits 80 / 15 / 5, $ARCIRCLE holders burn-to-vote on the coin's identity, the top contributor receives the 15% over 3 days and every contributor gets an airdrop.": "USDC 存放在托管合约中，72 小时结束前可随时提取自己的参与金。结束时按 80 / 15 / 5 拆分，$ARCIRCLE 持有者通过销毁投票决定代币身份，最大参与者分 3 天获得 15%，每位参与者都会获得空投。",
    "Every contributor gets an airdrop of the new coin — its size and timing aren't decided yet. The top contributor at the close also receives the 15% share, over 3 days.": "每位参与者都会获得新币空投——数量与时间尚未决定。截止时排名第一的参与者还将在 3 天内分批获得 15% 份额。",
    "Round #1 · next up: burn-to-vote": "Round #1 · 下一步：燃烧投票",
    "When the raise closes, $ARCIRCLE holders vote on the coin.": "募资结束后，$ARCIRCLE 持有者投票决定这枚币。",
    "1 vote = 1,000 $ARCIRCLE, sent to 0x…dEaD for good. Anyone holding $ARCIRCLE can vote, for 48 hours.": "1 票 = 1,000 $ARCIRCLE，永久发送至 0x…dEaD。任何持有 $ARCIRCLE 的人都可以在 48 小时内投票。",
