    "With this you'd be": "按此金额你将排名",
    "The top contributor at the close receives the 15%, over 3 days. Contributions can be withdrawn until the close, so #1 can change up to the last second — only the ranking at the close counts.": "截止时排名第一的参与者将在 3 天内获得 15%。截止前可以随时取回投入，所以第一名可能到最后一刻都在变化——只以截止时的排名为准。",
    "You took #1 — the 15% is yours if it holds at the close.": "你已成为第一——保持到截止即可获得 15%。",
    "You lost #1 to": "你的第一名被超越：",
    "New #1:": "新的第一名：",
    "Show this score on your site, README or docs": "把这个分数放到你的网站、README 或文档中",
    "Card": "卡片",
    "HTML": "HTML",
    "Markdown": "Markdown",
    "Image link": "图片链接",
    "It links back to this scan and updates by itself — the token is re-scanned every few hours.": "它会链接回本次扫描并自动更新——代币每隔几小时重新扫描一次。",
    "Your rank:": "你的排名：",
    "With this you'd be #1, ahead by": "按此金额你将排名第一，领先",
    "Put every idea into the candidate lists below — you check each list and publish it (one wallet signature per category).": "把所有提案填入下方的候选列表——逐一检查后按类别发布（每个类别签名一次）。",
    "Fill every category from the ideas": "用提案填满所有类别",
    "Filled:": "已填入：",
    "launch date left out — it's before the vote ends.": "个发射日期被排除——早于投票结束时间。",
    "Check each list, then press Publish in each category.": "检查每个列表，然后在每个类别中点击发布。",
    "Candidates go up first. Voting runs until the raise closes: 1 vote = 1,000 $ARCIRCLE, burned for good.": "候选先公布。投票持续到募资结束：1 票 = 1,000 $ARCIRCLE，永久销毁。",
    "Voting is open until the raise closes. Anyone holding $ARCIRCLE can vote — every vote burns 1,000 $ARCIRCLE.": "投票开放至募资结束。任何持有 $ARCIRCLE 的人都可以投票——每票销毁 1,000 $ARCIRCLE。",
    "Candidates are up — voting opens soon and runs until the raise closes. 1 vote = 1,000 $ARCIRCLE burned.": "候选已公布——投票即将开放，持续到募资结束。1 票 = 销毁 1,000 $ARCIRCLE。",
    "Until the raise closes": "直到募资结束",
    "Raise & voting close in": "募资与投票结束倒计时",
    "Raising · voting": "募资 · 投票中",
    "$ARCIRCLE holders vote on the coin while the raise runs.": "募资期间，$ARCIRCLE 持有者投票决定这枚币。",
    "1 vote = 1,000 $ARCIRCLE, sent to 0x…dEaD for good. Anyone holding $ARCIRCLE can vote until the raise closes.": "1 票 = 1,000 $ARCIRCLE，永久发送至 0x…dEaD。任何持有 $ARCIRCLE 的人都可以投票，直到募资结束。",
    "Live — raise and voting open": "进行中——募资与投票开放",
    "While the raise runs, $ARCIRCLE holders decide the name, ticker, logo, roadmap and date — 1,000 burned per vote.": "募资期间，$ARCIRCLE 持有者决定名称、代码、标志、路线图和日期——每票销毁 1,000 枚。",
    "USDC sits in an escrow contract and you can withdraw your own contribution any time before the 72 hours are up. While the raise runs, $ARCIRCLE holders burn-to-vote on the coin's identity. At the close it splits 80 / 15 / 5, the top contributor receives the 15% over 3 days and every contributor gets an airdrop.": "USDC 存放在托管合约中，72 小时结束前你可以随时取回自己的投入。募资期间，$ARCIRCLE 持有者通过燃烧投票决定这枚币的身份。截止时按 80 / 15 / 5 分配，排名第一的参与者在 3 天内获得 15%，所有参与者都会获得空投。",
    "Until the raise closes. Anyone holding $ARCIRCLE votes on name, ticker, logo, roadmap and launch date; every vote burns 1,000 $ARCIRCLE.": "直到募资结束。任何持有 $ARCIRCLE 的人都可以对名称、代码、标志、路线图和发射日期投票；每票销毁 1,000 $ARCIRCLE。",
    "Contributions, withdrawals and voting stop; the vote result is final. The escrow splits everything: 80% recipient, 15% treasury, 5% platform.": "投入、取回和投票全部停止，投票结果确定。托管合约分配全部资金：接收方 80%，金库 15%，平台 5%。",
    "Voting runs while the raise is open and closes with it. Anyone holding $ARCIRCLE can vote, as many times as they like.": "投票在募资期间开放，并随募资一起结束。任何持有 $ARCIRCLE 的人都可以投票，次数不限。",
    "Until the close": "直到截止",
    "Voting ends with the raise. The escrow sends 80% to the recipient, 15% to the treasury, 5% to the platform.": "投票随募资结束。托管合约将 80% 发给接收方，15% 发给金库，5% 发给平台。",
    "Identity voted on during the raise": "募资期间投票决定身份",
    "Name, ticker, logo and roadmap are all decided by $ARCIRCLE holders' votes while the raise runs — every vote burns 1,000 $ARCIRCLE. This card shows the shape of a round — it isn't a real one yet.": "名称、代码、标志和路线图都在募资期间由 $ARCIRCLE 持有者投票决定——每票销毁 1,000 $ARCIRCLE。此卡片只展示一轮的形式，还不是真实的一轮。",
