    "Utility · Cross-chain": "工具 · 跨链",
    "One $ARCIRCLE on three chains. Sending it from Arc locks it here and mints the same amount on the other chain; sending it back burns it there and unlocks it on Arc. The global supply stays 1,000,000,000.": "三条链上的同一个 $ARCIRCLE。从 Arc 发出时在这里锁定，并在另一条链上铸造相同数量；发回时在那边销毁，并在 Arc 上解锁。全球供应量始终为 1,000,000,000。",
    "Preview: the OMNI contracts are not deployed yet, so nothing can be sent. Prices, supply and the route below are shown so you can see how it will work.": "预览：OMNI 合约尚未部署，暂时无法发送。下方展示价格、供应量和路径，方便你了解它的运作方式。",
