    "On Arc": "在 Arc",
    "On Solana": "在 Solana",
    "On Robinhood Chain": "在 Robinhood Chain",
    "Locked in the Arc adapter": "锁定在 Arc 适配器",
    "Only Arc holds real supply. The other chains can mint only what Arc locked.": "只有 Arc 持有真实供应量。其他链只能铸造 Arc 已锁定的数量。",
    "Two independent verifiers (DVNs) must confirm every message.": "每条消息都必须由两个独立验证者（DVN）确认。",
    "Daily limits per route, and a pause switch held by a multisig.": "每条路径都有每日上限，并由多签持有暂停开关。",
    "Arc to Solana or Robinhood": "Arc → Solana 或 Robinhood",
    "Approve and send. The Arc adapter locks your $ARCIRCLE and LayerZero delivers a message; the other chain mints the same amount to your address.": "批准并发送。Arc 适配器锁定你的 $ARCIRCLE，LayerZero 传递消息，另一条链向你的地址铸造相同数量。",
    "Back to Arc": "返回 Arc",
    "Send from Solana or Robinhood Chain. The tokens are burned there and the adapter unlocks the same amount to you on Arc.": "从 Solana 或 Robinhood Chain 发送。代币在那边销毁，适配器在 Arc 上向你解锁相同数量。",
    "Between Solana and Robinhood": "Solana 与 Robinhood 之间",
    "Burned on one, minted on the other. Arc's locked amount doesn't change, so the total still adds up.": "一边销毁，另一边铸造。Arc 的锁定量不变，总数依然吻合。",
    "Each chain has its own market. When prices drift apart, buying where it's cheaper and selling where it's higher pulls them together.": "每条链都有自己的市场。价格出现差距时，在便宜处买入、在高价处卖出会把价格拉回一致。",
    "Built on LayerZero V2 OFT: an adapter on Arc for the existing token, mint/burn OFTs on the other chains. Not decided yet: the second verifier, daily limits, pool venues on Solana and Robinhood Chain, and the launch date.": "基于 LayerZero V2 OFT：Arc 上为现有代币部署适配器，其他链上为铸造/销毁 OFT。尚未确定：第二个验证者、每日上限、Solana 与 Robinhood Chain 的池子场所以及上线日期。",
    "Solana wallet (recipient)": "Solana 钱包（接收方）",
