    "Your ARCIRCLE token account on Solana is created for you on arrival.": "你在 Solana 上的 ARCIRCLE 代币账户会在到账时自动创建。",
    "Send from Solana": "从 Solana 发送",
    "Sending from Solana needs a Solana wallet — coming in the next version. Use Arc or Robinhood Chain as the source for now.": "从 Solana 发送需要 Solana 钱包——下个版本支持。目前请从 Arc 或 Robinhood Chain 发送。",
