    "Each hour the mine pays out by points × pickaxe × bonuses. In a live mine: join, post once on X, then claim. Pick your builder and pet below.": "每小时按 积分 × 镐子 × 加成 分配。在真实矿场：加入、在 X 发一次帖、然后领取。在下方选择你的建造者和宠物。",
    "Each hour's release is split by weight. Your browser does the hashing only while you press Start and the tab is open, and hands in its shares every 30 seconds.": "每小时的释放量按权重分配。只有点击开始且标签页打开时浏览器才计算哈希，每 30 秒提交一次份额。",
    "Edit the mine": "编辑矿场",
    "Enter the mine": "进入矿场",
    "Every swing that lands is a share, +1 point. Rare ores add more: copper to the Arc Crystal jackpot. The bar at the top shows when the next one is due.": "每次命中都是一份（+1 积分）。稀有矿石加得更多：从铜到 Arc 水晶大奖。上方的进度条显示下一份何时到来。",
    "Everyone who has found the Arc Crystal — 1 in 16,384 shares — stays here for good.": "所有挖到 Arc 水晶（16,384 份中的 1 份）的人都会永久留在这里。",
