    "The mine's tokens sit in the contract. Nobody — not the creator, not ARCIRCLE PAD — can take them back. Anyone can top a mine up.": "矿场代币存放在合约中。任何人——包括开矿者和 ARCIRCLE PAD——都无法取回。任何人都能追加。",
