    "launched less than 3 minutes ago": "发行不到 3 分钟",
    "older than 3 days": "超过 3 天",
    "liquidity under $800": "流动性低于 $800",
    "the desk couldn't quote a trade in this pool": "交易台无法在这个池子报价",
