    "Under a $5k market cap, a position is never held longer than 30 minutes; a crash-buy DCA position under a $10k market cap is sold after 1 hour.": "市值低于 $5k 时持仓绝不超过 30 分钟；急跌抄底补仓的持仓在市值低于 $10k 时 1 小时后卖出。",
