    "Not enough USDC on Arc for the fee.": "Arc 上的 USDC 不足以支付手续费。",
    "A playbook is benched when it has clearly lost money: 20+ trades averaging −1% or worse, or 10+ averaging −10% or worse. It keeps trading on paper and comes back to real money on its own when those results recover. All trades avg counts paper trades at half weight.": "当策略明显亏损时会被暂停：20 笔以上平均 −1% 或更差，或 10 笔以上平均 −10% 或更差。暂停期间仍以模拟盘交易，结果恢复后会自动回到真实资金。全部平均中模拟交易按一半权重计算。",
