    "On-chain check": "链上核对",
    "Open positions are held as tokens in the same contract; their value is what an exact sell quote from the contract says right now.": "持仓以代币形式存放在同一合约中；其价值按合约当前的精确卖出报价计算。",
    "Open positions keep their stop-losses in the rules, but nothing is checked until it runs again. The team has been alerted.": "规则中的止损仍然有效，但在重新运行前不会检查。团队已收到提醒。",
