    "The last 80 closed trades. A high win rate can still lose money if the losses are bigger than the wins — this shows it in dollars.": "最近平仓的 80 笔交易。胜率高也可能亏钱，只要亏损比盈利大——这里按美元显示。",
    "recent pump scalps (real and paper), replayed with a plain take-profit and stop-loss, no runner.": "笔最近的急涨短炒（真实和模拟），用简单止盈止损回放，不含追踪部分。",
