    "See why": "查看原因",
    "its launch floor (the pump scalp:": "发行底价（急涨短炒：",
    "), a top-10 dump under": "），前 10 钱包抛售跌幅低于",
    "(the pump scalp:": "（急涨短炒：",
    "of the desk if the coin falls back to its launch floor — the closer the floor, the bigger the buy can be": "（占交易台），如果币价跌回发行底价——底价越近，买入可以越大",
    "Half size after 3 losses in a row, when the last 20 real trades lost money in dollars, or once the day is down 5%; the minimum size when they lost twice what they made": "连续亏损 3 笔后、最近 20 笔真实交易按美元亏损时、或当天跌 5% 后用一半仓位；亏损是盈利的两倍时用最小仓位",
    "A pump scalp down": "急涨短炒在买入后",
    "A buy's size comes from the settings below (at least $3); these only cap it. They are also the most the trading key could spend in a day if it ever leaked — with no limit, the whole desk.": "买入仓位由下方设置决定（至少 $3），这些只是上限。它们也是交易密钥万一泄露时一天最多能花的金额——不设上限就是整个交易台。",
    "Sizing and pump scalp settings": "仓位与急涨短炒设置",
    "Most a buy may lose at the launch floor": "跌回发行底价时每笔最多亏损",
