    "Back to defaults": "恢复默认",
    "Signed by the owner wallet (no gas). They change how much a buy spends and which pump scalps pass — they can't make her trade. Used from her next run.": "由所有者钱包签名（无 gas）。它们只改变每笔买入的金额以及哪些急涨短炒能通过——不能让她交易。从下次运行开始生效。",
    "Daily post draft": "每日帖子草稿",
