    "defaults": "默认值",
    "Couldn't save — try again.": "保存失败——请重试。",
    "Saved. She uses them from her next run.": "已保存。从她的下次运行开始使用。",
    "Limits removed: a buy is sized by the desk's settings with no cap, and there's no daily limit.": "已取消限额：买入按交易台设置决定，没有上限，也没有每日限额。",
    "Early exit (fell right after the buy)": "提前退出（买入后立刻下跌）",
    "At the pump scalp's floor limit": "在急涨短炒的底价上限时",
    "a buy of at most": "每笔买入最多",
    "current exits": "当前退出设置",
    "best in the grid": "表中最佳",
    "minutes after the buy is sold at once": "分钟内跌这么多即刻卖出",
    "default value": "默认值",
    "due now": "即将执行",
    "open positions": "个持仓",
    "of the desk per buy": "（每笔，占交易台）",
    "Early exit: in the first": "提前退出：买入后的前",
    "Real money has stricter rules than paper. An Argus pool starts at its launch price, and if the early buyers all sell, the price falls back there in one block. So a real buy needs the price at most 6× its launch floor (the pump scalp: 7×), a top-10 sell-off that would drop it less than 80% (the pump scalp: 60%), and no critical flag in the last 6 hours.": "真实资金的规则比模拟更严格。Argus 池从发行价开始，如果早期买家全部卖出，价格会在一个区块内跌回那里。所以真实买入要求价格不超过发行底价的 6 倍（急涨短炒：7 倍），前 10 钱包全部卖出造成的跌幅低于 80%（急涨短炒：60%），并且最近 6 小时没有严重警告。",
    "A buy starts at 6% of the desk (at least $3) and is sized by risk: if the coin fell back to its launch floor, it would lose at most 1.25% of the desk. Size halves after 3 real losses in a row, when the last 20 real trades lost money in dollars, or once the day is down 5%, and drops to the $3 minimum when those trades lost twice what they made. A pump scalp that falls 5% within 2 minutes of the buy is sold at once. The desk's owner can tune these within fixed bounds by signing with the owner wallet; the settings can't make her trade.": "每笔买入从交易台的 6%（至少 $3）开始，并按风险决定大小：即使币价跌回发行底价，也最多亏损交易台的 1.25%。连续 3 笔真实亏损后、最近 20 笔真实交易按美元亏损时、或当天下跌 5% 后，仓位减半；如果这些交易亏损是盈利的两倍，则降到最低 $3。急涨短炒买入后 2 分钟内下跌 5% 会立即卖出。交易台所有者可以用所有者钱包签名，在固定范围内调整这些设置；设置不能让她交易。",
    "At most 10 positions open and 8 buys an hour; $2 always stays in cash; the contract's own limits cap each buy and each day. During the warm-up (the first 25 real trades): $3 a trade and at most 6 buys an hour. Each DCA tranche is $2. Since 30 Sep 2026 real money goes only through the Pump scalp; the other playbooks keep trading on paper so the desk keeps learning from them.": "最多同时持有 10 个仓位，每小时最多买入 8 次；始终保留 $2 现金；合约自身的限额限制每笔和每天的金额。热身期（前 25 笔真实交易）：每笔 $3，每小时最多 6 次。每次 DCA 加仓 $2。自 2026 年 9 月 30 日起，真实资金只通过急涨短炒交易；其他策略继续模拟交易，让交易台持续学习。",
    "A call is about risk over the next 24 hours, never about price direction — not a signal to buy or sell.": "判断针对未来 24 小时的风险，不是价格方向——不是买卖信号。",
