    "No markets with orders yet — open any Arc token above and place the first one.": "还没有挂单的市场——在上方打开任意 Arc 代币并下第一单。",
    "No trades in this pool in the last 3 days.": "该池近3天没有交易。",
    "Orders": "订单",
