    "Price alert": "价格提醒",
    "Price step": "价格步长",
    "Raise the slippage limit above": "请将滑点上限提高到",
    "Reading the pool's trades…": "正在读取池的交易…",
    "Released evenly over the period and filled in parts from the pool — never above your price limit. One signature.": "在期间内均匀释放并分批由池成交——绝不超过你的价格上限。只需一次签名。",
    "Replace order": "替换订单",
    "Round trip": "往返成本",
