    "Swaps the USDC for $ARCIRCLE through ARCIRCLE Orders and adds it to your lock": "通过 ARCIRCLE Orders 把 USDC 换成 $ARCIRCLE 并加入锁仓",
    "That lock isn't a max lock.": "这不是最长锁仓。",
