    "New in v2": "v2 新功能",
    "On a phone, UP and DOWN stay pinned to the bottom of the screen with the quick amounts, so you can bet without scrolling.": "在手机上，UP 和 DOWN 按钮连同快捷金额固定在屏幕底部，无需滚动即可下注。",
    "Before you bet, the box shows what your amount would pay if UP wins and if DOWN wins (if nobody else bets after you), and warns when it's under the smallest or over the largest bet.": "下注前会显示你的金额在 UP 赢和 DOWN 赢时能拿到多少（若之后无人再下注），低于最小或高于最大下注额时会提示。",
    "Each round finishes with a 3-2-1 countdown, then \"Reading the pool…\" until the result lands; the winning side lights up.": "每回合以 3-2-1 倒计时结束，结果出来前显示\"正在读取池子…\"；获胜一方会亮起。",
    "Market chips show the time left to bet, the pot and a small line of recent prices; a chip pulses in its last 30 seconds.": "市场标签显示距下注截止的时间、奖池和最近价格小图；最后 30 秒标签会闪烁。",
    "ARCIA calls every round (UP if the coin is above its price to beat, DOWN if below) before bets close, and her record is kept next to \"the crowd\" (the side with more money). It's for fun, not advice.": "ARCIA 会在下注截止前判断每个回合（价格高于基准价则 UP，低于则 DOWN），并与\"大众\"（资金更多的一方）一起记录战绩。仅供娱乐，非投资建议。",
    "The last 10 results sit under the token's name, with a dot where ARCIA's call was scored. Reactions (hot, to the moon, cold, watching) can be left on the live round.": "代币名称下方显示最近 10 回合结果，ARCIA 的判断被计分处会有圆点。可以对进行中的回合留下反应（火热、冲上月球、冷淡、围观）。",
    "The bell on a market reminds you 30 seconds before bets close, every round, in this browser. Badges come with your first call, first win, streaks of 3, 5 and 10, and 10, 50 and 100 rounds.": "点击市场上的铃铛，此浏览器会在每回合下注截止前 30 秒提醒你。首次预测、首胜、3/5/10 连胜、10/50/100 回合可获得徽章。",
    "All markets lets you bet straight from a tile with your amount. The weekly leaderboard is a season that resets every Monday 00:00 UTC. In Telegram, /predict lists the live rounds.": "在 All markets 中可直接用你的金额从卡片下注。每周排行榜是每周一 00:00 UTC 重置的赛季。在 Telegram 中用 /predict 查看进行中的回合。",
