    "Set the take-profit above your price and the stop-loss below it — or untick the bracket.": "止盈要高于你的价格、止损低于它——或取消勾选。",
    "Sign order": "签名订单",
    "Sign the orders": "签名各订单",
    "Splits one buy into several limit orders spread over a price range — one signature each, no gas.": "把一笔买入拆成分布在价格区间内的多笔限价单——每笔一次签名，无 gas。",
    "Splits one sell into several limit orders spread over a price range — one signature each, no gas.": "把一笔卖出拆成分布在价格区间内的多笔限价单——每笔一次签名，无 gas。",
    "Spread the range a little wider.": "把区间再拉开一点。",
    "That's far from the pool price — it may wait a long time, and it only fills if the price gets there.": "离池价很远——可能要等很久，只有价格到那里才会成交。",
    "The chart shows up when a market is open.": "打开市场后显示图表。",
    "The executor hasn't checked in a while — fills may be late.": "执行器有一阵没检查了——成交可能会晚。",
    "The executor is low on gas — fills may be late.": "执行器 gas 不足——成交可能会晚。",
    "The executor isn't running yet — orders wait until it starts.": "执行器还没运行——订单会等到它启动。",
    "The faint rows are prices around the pool: tap one to start an order there.": "浅色行是池价附近的价格：点一下就以那个价格开始下单。",
    "This buy is far above the pool price — check the price: it would fill right away.": "这笔买单远高于池价——请核对价格：会立即成交。",
    "This sell is far below the pool price — check the price: it would fill right away.": "这笔卖单远低于池价——请核对价格：会立即成交。",
    "Waits for the price to fall through the trigger, then sells at market — never below your slippage limit.": "等价格跌破触发价后按市价卖出——不低于你的滑点限制。",
    "Waits for the price to rise through the trigger (a breakout), then buys at market.": "等价格涨破触发价（突破）后按市价买入。",
    "When the buy fills, this page shows a button to sign both — this browser keeps them until then.": "买单成交后，本页会显示签名这两单的按钮——在那之前由这个浏览器保存。",
    "Wraps first (one transaction)": "先包装（一笔交易）",
