    "of these prices are above the pool price — those fill right away.": "个价格高于池价——这些会立即成交。",
    "of these prices are below the pool price — those fill right away.": "个价格低于池价——这些会立即成交。",
    "placed — the rest didn't go through:": "笔已挂出——其余未成功：",
    "press Replace order to move it": "按“替换订单”即可移动",
    "received at least": "至少收到",
    "same amount": "相同数量",
    "saved at today's rate": "按今天的费率省下",
    "set its take-profit and stop-loss now.": "现在设置止盈和止损。",
    "the price never reached it": "价格始终没到",
    "the price never reached the trigger": "价格始终没触及触发价",
    "top up the balance or the approval — it fills from where it left off": "补足余额或授权——会从中断处继续成交",
    "vs pool": "对比池价",
    "★ keeps a market at the front": "★ 让市场固定在前面",
    "cancelled": "已取消",
    "order": "笔",
    "orders": "笔",
    "24h": "24小时",
    "Limit, stop, TP/SL and scaled orders — Arc, Robinhood and Solana": "限价、止损、止盈/止损和分批挂单——Arc、Robinhood 和 Solana",
    "Limit · stop · TP/SL · scaled · DCA": "限价 · 止损 · 止盈/止损 · 分批 · DCA",
    "On a wide screen the order form runs down the right from the top and stays in view as you scroll; the price alert is a small pop-up on its button. A slim strip with the price, its 24h change and Buy / Sell follows you down the page.": "宽屏上，下单框从右上方一路排下，滚动时始终可见；价格提醒变成按钮上的小弹窗。一条显示价格、24 小时涨跌和买 / 卖的细条会跟着页面往下走。",
    "Simple shows Limit and Market; Pro shows every type, the book's price step and keyboard keys (B and S pick the side, Enter places, / goes to the token box).": "简单模式只显示限价和市价；专业模式显示所有类型、订单簿价格步长和键盘快捷键（B 和 S 选方向，Enter 下单，/ 跳到代币输入框）。",
    "Click the chart to use that price. Drag one of your limit-order lines to a new price, then press Replace order — that signs the new order and cancels the old one.": "点击图表即可使用该价格。把你的限价单价格线拖到新价格，再按“替换订单”——会签名新订单并取消旧订单。",
    "Each order type has a small drawing and one line on how it works. Next to the price you see how far it is from the pool price — and a buy far above it (or a sell far below) asks for a second press.": "每种订单类型都配有一张小图和一句说明。价格旁显示与池价的距离——远高于池价的买单（或远低于池价的卖单）需要再按一次确认。",
    "ARCIA levels: the 24-hour and 3-day lows and highs from the pool's own trades, one tap from the price box. They're levels to consider, not advice.": "ARCIA 价位：取自该池自身成交的 24 小时和 3 天最低价与最高价，在价格框里一点即可填入。仅供参考，不是投资建议。",
    "Scaled orders split one buy or sell into 3 to 10 limit orders over a price range (one signature each, no gas). A limit buy can carry a take-profit and stop-loss: once it fills, this browser shows a button to sign both.": "分批挂单把一笔买入或卖出拆成价格区间内的 3 到 10 笔限价单（每笔一次签名，无 gas）。限价买单可附带止盈和止损：成交后，这个浏览器会显示签名两单的按钮。",
    "Expiry and slippage are one-tap chips; the summary shows where the fee goes (half buys and burns $ARCIRCLE — or what a holder saves) and, on Robinhood Chain, how much ETH gets wrapped first. The steps ahead (wrap, approve, sign, place) show before you press, with an approval that already covers it ticked.": "到期和滑点改为一键选择的标签；摘要会显示手续费去向（一半用于买入并销毁 $ARCIRCLE——持有者则显示省下多少），以及在 Robinhood Chain 上要先包装多少 ETH。按下之前就能看到接下来的步骤（包装、授权、签名、下单），已足额授权的会打勾。",
    "Save the form as a preset, or Repeat last: the same side, type and distance from the pool (and, in the same market, the same amount).": "把下单框保存为预设，或用“重复上一单”：相同的方向、类型和距池价的距离（在同一市场还会带上相同数量）。",
    "An empty book shows a faint ladder of prices around the pool; each level has a size mark, and hovering shows its orders and distance from the pool. A new order flies into its row.": "空的订单簿会显示池价附近的浅色价格阶梯；每档都有大小标记，悬停可看到订单数和距池价的距离。新订单会飞入对应的行。",
    "All markets has a search box, each market's 24-hour change and a line of its fills, and ★ keeps a market at the front.": "全部市场里加入了搜索框、每个市场的 24 小时涨跌和成交走势线，★ 能把市场固定在前面。",
    "History filters by filled, expired and cancelled (cancelled ones fold away), and says why an order didn't fill. Timed orders show their parts and when the next one is released. Cancel all asks once more.": "历史记录可按已成交、已到期、已取消筛选（已取消的会折叠），并说明订单为何没成交。定时订单会显示每一份以及下一份何时释放。全部取消会再确认一次。",
    "Under your orders: what your fills in this market add up to (average buy and sell against the pool) and how much of their fees went to buy and burn $ARCIRCLE. A fill comes with a toast of what came in and a burst of confetti; the share image shows the fill and its ring.": "在你的订单下方：你在这个市场的成交汇总（平均买价和卖价对比池价），以及其中多少手续费用于买入并销毁 $ARCIRCLE。成交时会弹出收到多少的提示并撒出彩纸；分享图片会显示成交和成交环。",
    "Buy at your price or lower. Signed in your wallet — no gas; your tokens stay with you until it fills.": "以你的价格或更低价买入。只需在钱包里签名——无 gas；成交前资产一直留在你的钱包。",
    "Sell at your price or higher. Signed in your wallet — no gas; your tokens stay with you until it fills.": "以你的价格或更高价卖出。只需在钱包里签名——无 gas；成交前代币一直留在你的钱包。",
