    "That address isn't an ERC-721 collection on Robinhood Chain.": "这个地址不是 Robinhood Chain 上的 ERC-721 系列。",
    "The keeper can't act yet: its wallet isn't the vault's keeper": "Keeper 还无法运行：它的钱包还不是金库的 keeper",
    "The keeper claims fees, buys NFTs and runs the draws. Anyone can check every step on-chain.": "Keeper 负责领取手续费、购买 NFT 和运行开奖。每一步任何人都可以在链上核查。",
    "The keeper hasn't run yet": "Keeper 还没有运行过",
