    "From trading fees to a winner": "从交易手续费到中奖者",
    "Every raffle on the page has \"How this draw ran\": the purchase, the holder snapshot with its Merkle root, the 6-hour challenge window, the commit, the reveal with the drawn ticket and the transfer to the winner — each with its transaction on Robinhood Chain.": "页面上每次抽奖都有“这次开奖的过程”：购买、带 Merkle 根的持有人快照、6 小时质疑期、承诺、抽出中奖票的揭示以及发送给中奖者——每一步都附 Robinhood Chain 交易。",
    "\"Check my ticket\" fetches your Merkle proof and checks it in your browser against the root the vault holds on-chain, then shows your ticket range and whether the drawn ticket is yours.": "“查看我的票”会获取你的 Merkle 证明，并在你的浏览器里与金库链上的根直接比对，然后显示你的票号范围以及中奖票是否属于你。",
    "\"The list (JSON)\" downloads the whole list the root commits to: every wallet, its ticket range and its weight (held, locked, veARCIRCLE).": "“名单（JSON）”可下载根所承诺的完整名单：每个钱包、它的票号范围和权重（持有、锁仓、veARCIRCLE）。",
    "was open": "之前：进行中",
    "was drawn": "之前：已开奖",
    "was held": "之前：持有中",
