    "Pick your launchpad.": "选择你的发射台。",
    "ArcPad on Arc opens a real Uniswap v4 pool the second you launch — locked liquidity, tradeable from block one. Or launch on Argus, Pons (Robinhood Chain) or Pump.fun (Solana) from the same form, with the fee split built in.": "Arc 上的 ArcPad 在你发行的那一刻就开启真实的 Uniswap v4 池——流动性锁定，从第一个区块起即可交易。也可以用同一个表单在 Argus、Pons（Robinhood Chain）或 Pump.fun（Solana）发行，手续费分成已内置。",
