    "Holding $ARCIRCLE multiplies your reward weight. Counted on Arc (wallet + ARCIRCLE Staking) and Robinhood Chain; a boost lasts 7 days.": "持有 $ARCIRCLE 会放大你的奖励权重。统计 Arc（钱包 + ARCIRCLE Staking）和 Robinhood Chain 上的持仓；加成有效 7 天。",
    "Staking is free. Estimates use today's rewards and stakers; they change as those do. Not financial advice.": "质押免费。预估基于今天的奖励和质押者，会随之变化。非投资建议。",
    "Adding or renewing restarts your lock from now; it can't end earlier than it does now": "追加或续期会从现在重新开始锁定，且不能早于当前结束时间",
