    "Stake $ARCIA for 1 to 20 days and it becomes veARCIA. Rewards in $ARCIA stream to stakers every second, longer locks earn up to 2x, and holding $ARCIRCLE adds up to 2x more. veARCIA is also how you'll take part in the ARCIA AI ecosystem and its governance.": "质押 $ARCIA 1 到 20 天即成为 veARCIA。$ARCIA 奖励每秒发放给质押者，锁得越久最多 2 倍，持有 $ARCIRCLE 还可再加最多 2 倍。veARCIA 也将是参与 ARCIA AI 生态和治理的方式。",
