    "veARCIA is open": "veARCIA 已开放",
    "veARCIA is recorded over time for the votes to come — the ARCIA AI ecosystem and its governance.": "veARCIA 按时间记录，用于未来的投票——ARCIA AI 生态与治理。",
    "veARCIA tier": "veARCIA 等级",
    "veARCIA tiers": "veARCIA 等级",
    "ARCIA chat": "ARCIA 聊天",
    "a day to": "每日发给",
    "to claim": "可领取",
    "unlocks in": "解锁倒计时",
    "veARCIA tiers and perks": "veARCIA 等级与权益",
    "Stake $ARCIA on Robinhood Chain and choose a lock of 1 to 20 days. Your $ARCIA becomes veARCIA: the amount × a lock multiplier, from 1.0x for 1 day up to 2.0x for 20 days (10 days is 1.47x). veARCIA can't be transferred. It's your weight for the $ARCIA rewards, and it's how you'll take part in the ARCIA AI ecosystem and its governance as they open.": "在 Robinhood Chain 质押 $ARCIA 并选择 1 到 20 天的锁定。你的 $ARCIA 变为 veARCIA：数量 × 锁定倍率，1 天 1.0x 到 20 天 2.0x（10 天为 1.47x）。veARCIA 不可转让。它是你领取 $ARCIA 奖励的权重，也是将来参与 ARCIA AI 生态和治理的方式。",
    "Rewards are paid in $ARCIA from the veARCIA reward pool, which streams out over 20 days: every second, the stream is shared by everyone staked, in proportion to their reward weight (veARCIA × your $ARCIRCLE boost). The page shows today's daily rewards and the yearly rate they work out to. Neither is fixed: they follow the reward pool and the total staked, so they can go up or down.": "奖励以 $ARCIA 从 veARCIA 奖励池发放，奖励池在 20 天内持续释放：每一秒都按奖励权重（veARCIA × 你的 $ARCIRCLE 加成）分给所有质押者。页面显示今天的每日奖励及对应年化。两者都不固定：随奖励池和总质押量变化。",
    "Claim whenever you like — claiming is free (just gas) and doesn't touch your stake. Or compound: your $ARCIA rewards join your stake in one transaction, with the same lock and no tokens moving. Rewards you've earned stay yours even after you withdraw.": "随时领取——领取免费（仅 gas），不影响质押。或复投：一笔交易把 $ARCIA 奖励加入质押，锁定不变、无需转移代币。已赚取的奖励在取回后仍归你。",
    "Staking is free. One position per wallet: adding $ARCIA or picking a new length restarts the lock from now, and it can't end earlier than it already would.": "质押免费。每个钱包一个仓位：追加 $ARCIA 或选择新期限会从现在重新开始锁定，且不能早于原本的结束时间。",
    "After the lock ends, withdrawing is free. Until you renew, an ended lock counts at 1.0x.": "锁定结束后取回免费。续期前，已结束的锁定按 1.0x 计算。",
    "Auto-renew keeps your lock — and its multiplier — running until you turn it off; then the full length counts down from that moment. While it's on, an early exit costs 50%.": "自动续期会让锁定及其倍率一直有效，直到你关闭；关闭后从那一刻开始完整倒计时。开启期间提前退出成本为 50%。",
    "Withdrawing before the lock ends costs a share of what you take out: the time left ÷ the lock's full length, at most 50%. 5 days left of a 10-day lock costs 50% (the cap); 2 days left of a 10-day lock costs 20%. The penalty is burned (sent to 0x…dEaD). The page shows the exact amount before you sign.": "锁定结束前取回需支付取回数量的一部分：剩余时间 ÷ 锁定总时长，最多 50%。10 天锁定剩 5 天为 50%（上限），剩 2 天为 20%。罚金被销毁（发送至 0x…dEaD）。签名前页面会显示确切金额。",
    "Holding $ARCIRCLE multiplies your reward weight: 1.2x from 1,000,000, 1.5x from 5,000,000 and 2.0x from 10,000,000 $ARCIRCLE. It counts $ARCIRCLE in your wallet on Arc, locked in ARCIRCLE Staking (veARCIRCLE) and on Robinhood Chain. The site checks your holding and signs a boost note; you apply it with one transaction, and it lasts 3 days — refresh it from this page. If your holding drops, a newer note lowers it, and an expired boost goes back to 1.0x.": "持有 $ARCIRCLE 会放大奖励权重：1,000,000 起 1.2x、5,000,000 起 1.5x、10,000,000 起 2.0x。统计 Arc 钱包、ARCIRCLE Staking（veARCIRCLE）中锁定的以及 Robinhood Chain 上的 $ARCIRCLE。网站核对持仓并签发加成凭证；一笔交易即可应用，有效 3 天——在本页刷新。持仓减少时新凭证会下调，过期后回到 1.0x。",
    "Bronze from 10,000 veARCIA, Silver from 100,000, Gold from 1,000,000 and Diamond from 5,000,000. Each tier gets more time with ARCIA in her chat every day (+100, +200, +400 or +800 messages) and a badge on ArcPad comments. veARCIA is recorded over time, so it can be counted at any past moment in the votes to come for the ARCIA AI ecosystem and its governance.": "10,000 veARCIA 起为 Bronze，100,000 起为 Silver，1,000,000 起为 Gold，5,000,000 起为 Diamond。每档每天可与 ARCIA 多聊（+100、+200、+400 或 +800 条消息），并在 ArcPad 评论上显示徽章。veARCIA 按时间记录，未来 ARCIA AI 生态与治理投票可按任意过去时间点统计。",
    "Staked $ARCIA and the rewards you've earned can only go to you: no one else can move them, pause the contract or change the multipliers, the 20-day stream or the 50% cap. The contract is new, so stake what you're comfortable holding for the lock you pick. Nothing here is financial advice.": "质押的 $ARCIA 和已赚取的奖励只能归你：任何人都无法转走、暂停合约或修改倍率、20 天释放和 50% 上限。合约是新的，请只质押你愿意在所选期限内持有的数量。非投资建议。",
    "Stake $ARCIA for 1–20 days and earn $ARCIA every second — $ARCIRCLE holders boost up to 2.0x": "质押 $ARCIA 1–20 天，每秒获得 $ARCIA 奖励 — $ARCIRCLE 持有者最高 2.0x 加成",
