    "A signature, no gas. The keeper stops it then — the round open for bets still runs and settles.": "只需签名，无需 Gas。届时由 keeper 停止市场，正在下注的回合仍会进行并结算。",
    "ARCIA filled this in": "ARCIA 已帮你填好",
    "Alerts in this tab": "仅在此标签页提醒",
    "Alerts on Telegram": "Telegram 提醒",
    "Bet with play money on the real rounds — nothing leaves your wallet": "用练习资金押注真实回合——钱包里的资产不会动",
    "Bets are real again.": "现在恢复真实下注。",
    "End date for": "结束日期：",
    "Fan tier from the $ARCIA held on Robinhood Chain": "根据在 Robinhood Chain 持有的 $ARCIA 决定的粉丝等级",
