    "Nobody on the other side by the lock? Everyone gets their full stake back — no fee.": "截止时对面没人？所有人全额退还，不收手续费。",
    "Not enough play balance — reset it to start over.": "练习余额不足——重置后重新开始。",
    "Past seasons": "往届赛季",
    "Play balance": "练习余额",
    "Play balance reset": "练习余额已重置",
    "Play for real": "真实下注",
    "Play money on the real rounds — nothing leaves your wallet.": "在真实回合中使用练习资金——钱包资产不会动。",
    "Practice bet": "练习下注",
    "Practice bets go on the real rounds with play money and settle on the real result. Nothing leaves your wallet. With nobody on the other side, practice pays an even pot.": "练习下注用练习资金押在真实回合上，按真实结果结算。钱包资产不会动。对面没人时，练习按等额奖池计算。",
    "Practice loss": "练习失利",
