    "Each skill needs a tag (a-z, 0-9, -), a name and a price of at least 0.10 USDC.": "每个技能都需要标签（a-z、0-9、-）、名称和至少 0.10 USDC 的价格。",
    "Sign in with your wallet — a message, no gas…": "用钱包登录 — 签名一条消息，无需 Gas…",
