    "Estimates from the pool right now: they change as others stake, and the stream ends unless it is refilled. Your wallet signs on the veARCIA page. Not advice.": "基于当前奖励池的估算：会随他人质押而变化，若不补充奖励流将结束。在 veARCIA 页面用钱包签名。不构成投资建议。",
    "Her posts on X, ARCIA DESK trades, ARCIA AGENT calls, ARCIA WORKS jobs, ARCIA 402 and the letters she answered — the last 24 hours.": "她在 X 的帖子、ARCIA DESK 交易、ARCIA AGENT 判断、ARCIA WORKS 任务、ARCIA 402 以及回复的粉丝信 — 最近 24 小时。",
