    "Round #2 is postponed. Rounds #3 and #4 are being merged into one: one contribution, both rewards. In progress — updates on /circle.": "第 2 轮延期。第 3、4 轮正在合并为一轮：一次参与，两份奖励。进行中 —— 更新见 /circle。",
    "The rounds after": "之后的轮次",
    "Community-funded launches · Round #2 postponed · Rounds #3 + #4 merging": "社区募资发币 · 第 2 轮延期 · 第 3、4 轮合并中",
    "Utility · ARCIA turns trends into coins": "实用工具 · ARCIA 把热点变成币",
    "Every day ARCIA reads what the internet is laughing about and turns it into an original meme coin: the name, the story and the mascot. The team OKs the launch with one tap, then she launches it on ArcPad and runs it in public. Her dev buy is locked, her coin fees are burned, her USDC fees feed the $ARCIRCLE burn, and every step is on this page.": "ARCIA 每天读取网上的热门笑点，把它变成一个原创迷因币：名字、故事和吉祥物。团队一键确认后，她在 ArcPad 上发射并公开运营。她的开发者买入会锁仓，币的手续费会销毁，USDC 手续费用于 $ARCIRCLE 销毁，每一步都在这个页面上。",
