    "Size": "仓位",
    "Start with $10,000 of play money. Trade BTC, ETH and SOL with live prices and climb the board — nothing on-chain, nothing to lose.": "以 $10,000 模拟资金开始。用实时价格交易 BTC、ETH 和 SOL，冲击排行榜 — 不上链，也不会亏钱。",
    "Take-profit / stop-loss saved.": "已保存止盈 / 止损。",
